create policy "restaurant_settings_update_owner" on public.restaurant_settings for update using (public.same_restaurant(restaurant_id) and public.has_role(array['owner'])) with check (public.same_restaurant(restaurant_id) and public.has_role(array['owner']));
create policy "restaurant_settings_delete_owner" on public.restaurant_settings for delete using (public.same_restaurant(restaurant_id) and public.has_role(array['owner']));

